from pathlib import Path

import pytest

NOTES_DIR = "notes"


def first_readable(names: list[str]) -> str:
    """Return the text of the first name in `names` that is a readable file
    inside the directory `notes` (relative to the working directory).

    Subdirectory names such as "sub/b.txt" are valid. Names are untrusted:
    absolute paths, ".." segments, symlinks, or any other spelling that
    resolves to a location outside `notes` must never be read and are
    skipped. Missing, unreadable, or non-file entries (e.g. directories) are
    skipped too. Returns "" when no name yields a readable file.
    """
    try:
        root = Path(NOTES_DIR).resolve(strict=True)
    except (OSError, RuntimeError):
        return ""
    for name in names:
        if not name or "\x00" in name:
            continue
        try:
            candidate = (root / name).resolve(strict=True)
            if not candidate.is_relative_to(root) or candidate == root:
                continue
            if not candidate.is_file():
                continue
            return candidate.read_text()
        except (OSError, ValueError, RuntimeError, UnicodeDecodeError):
            continue
    return ""


@pytest.fixture
def workdir(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    (tmp_path / "notes" / "sub").mkdir(parents=True)
    (tmp_path / "notes" / "a.txt").write_text("alpha")
    (tmp_path / "notes" / "sub" / "b.txt").write_text("bravo")
    (tmp_path / "secret.txt").write_text("secret")
    monkeypatch.chdir(tmp_path)
    return tmp_path


def test_empty_list(workdir: Path) -> None:
    assert first_readable([]) == ""


def test_first_file_read(workdir: Path) -> None:
    assert first_readable(["a.txt"]) == "alpha"


def test_subdirectory_file(workdir: Path) -> None:
    assert first_readable(["sub/b.txt"]) == "bravo"


def test_skips_missing(workdir: Path) -> None:
    assert first_readable(["nope.txt", "a.txt"]) == "alpha"


def test_first_readable_wins(workdir: Path) -> None:
    assert first_readable(["sub/b.txt", "a.txt"]) == "bravo"


def test_none_readable(workdir: Path) -> None:
    assert first_readable(["nope.txt", "also/missing.txt"]) == ""


def test_directory_is_skipped(workdir: Path) -> None:
    assert first_readable(["sub", "a.txt"]) == "alpha"
    assert first_readable(["sub"]) == ""


def test_empty_name_is_skipped(workdir: Path) -> None:
    assert first_readable(["", "a.txt"]) == "alpha"
    assert first_readable([""]) == ""


def test_dot_name_is_skipped(workdir: Path) -> None:
    assert first_readable([".", "a.txt"]) == "alpha"


def test_parent_traversal_blocked(workdir: Path) -> None:
    assert first_readable(["../secret.txt"]) == ""


def test_parent_traversal_then_valid(workdir: Path) -> None:
    assert first_readable(["../secret.txt", "a.txt"]) == "alpha"


def test_nested_traversal_blocked(workdir: Path) -> None:
    assert first_readable(["sub/../../secret.txt"]) == ""


def test_traversal_that_stays_inside_is_ok(workdir: Path) -> None:
    assert first_readable(["sub/../a.txt"]) == "alpha"


def test_absolute_path_blocked(workdir: Path) -> None:
    assert first_readable([str(workdir / "secret.txt")]) == ""


def test_absolute_path_inside_notes_blocked_or_read(workdir: Path) -> None:
    # An absolute spelling must never escape; one pointing inside notes may
    # be either read or skipped, but must not leak anything outside.
    result = first_readable([str(workdir / "notes" / "a.txt")])
    assert result in ("", "alpha")


def test_backslash_traversal_blocked(workdir: Path) -> None:
    assert first_readable(["..\\secret.txt"]) == ""


def test_null_byte_name_skipped(workdir: Path) -> None:
    assert first_readable(["a.txt\x00", "sub/b.txt"]) == "bravo"


def test_symlink_file_escape_blocked(workdir: Path) -> None:
    (workdir / "notes" / "link.txt").symlink_to(workdir / "secret.txt")
    assert first_readable(["link.txt"]) == ""
    assert first_readable(["link.txt", "a.txt"]) == "alpha"


def test_symlink_dir_escape_blocked(workdir: Path) -> None:
    outside = workdir / "outside"
    outside.mkdir()
    (outside / "x.txt").write_text("leak")
    (workdir / "notes" / "dirlink").symlink_to(outside, target_is_directory=True)
    assert first_readable(["dirlink/x.txt"]) == ""


def test_symlink_inside_notes_ok(workdir: Path) -> None:
    (workdir / "notes" / "inner.txt").symlink_to(workdir / "notes" / "a.txt")
    assert first_readable(["inner.txt"]) == "alpha"


def test_prefix_sibling_directory_blocked(workdir: Path) -> None:
    sibling = workdir / "notes2"
    sibling.mkdir()
    (sibling / "c.txt").write_text("sibling")
    assert first_readable(["../notes2/c.txt"]) == ""


def test_unreadable_file_skipped(workdir: Path) -> None:
    locked = workdir / "notes" / "locked.txt"
    locked.write_text("locked")
    locked.chmod(0)
    try:
        assert first_readable(["locked.txt", "a.txt"]) == "alpha"
    finally:
        locked.chmod(0o644)


def test_non_utf8_file_skipped(workdir: Path) -> None:
    (workdir / "notes" / "bin.dat").write_bytes(b"\xff\xfe\x00\x80")
    assert first_readable(["bin.dat", "a.txt"]) == "alpha"


def test_missing_notes_directory(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    monkeypatch.chdir(tmp_path)
    assert first_readable(["a.txt"]) == ""

